import ast,hashlib,json,pathlib,re,shlex,subprocess,time
root=pathlib.Path.cwd();out=root/'evidence/paper-equity-execution-20261030/final-verification';packet=root/'evidence/paper-equity-execution-20261030/upgrade-package-final'
paths=[p for p in subprocess.check_output(['git','ls-files','operator/native-paper-ec2','evidence/paper-equity-execution-20261030/upgrade-package-final'],text=True).splitlines()if pathlib.Path(p).is_file()]
def digest():return {p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()for p in paths}
before=digest();results=[]
for i,cmd in enumerate([['python3','-B','operator/native-paper-ec2/test-paper-equity-execution-template.py'],['python3','-B','operator/native-paper-ec2/test-forward-original-upgrade.py'],['python3','-B','operator/native-paper-ec2/test-prepare-reservation-priority-package-20261030.py']]):
 start=time.time();r=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True);(out/f'test-{i+1}.txt').write_text(r.stdout);m=re.search(r'Ran (\d+) tests?',r.stdout);results.append({'command':cmd,'returncode':r.returncode,'tests':int(m.group(1))if m else None,'seconds':round(time.time()-start,3)})
