e={'source':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'newSource':pins['source'],'previousSource':pins['previousSource'],'commands':results,'sourceAndArtifactsUnchanged':before==after,'sourceSha256':before,'indexSha256':pins['indexSha256'],'driverSha256':pins['driverSha256'],'transportSha256':pins['transportSha256'],'ownerCommandSha256':pins['ownerCommandSha256'],'ownerCommandShellAndPythonSyntax':'PASS not executed','configurationSha256':pins['configurationSha256'],'fourDeepTwoHeldPaperOnly':pins['deepSlots']==4 and pins['financialPositionLimit']==2,'riskAndFinancialSemanticsChanged':pins['riskChanged']and pins['financialSemanticsChanged'],'hardControlsCleared':pins['hardFinancialControlsClearedByInstaller'],'ownerDailyLossResetInvoked':pins['ownerDailyLossResetInvoked'],'postStartExecutableRollbackAllowed':pins['postStartExecutableRollbackAllowed'],'supersedesUnappliedA1':True,'targetServiceOrFinancialOrProviderActions':0,'staged':False,'published':False,'deployed':False,'acceptance':'exact offline packet assembly/fixture verification only; no forward operation claim'};(out/'verification.json').write_text(json.dumps(e,indent=2)+'\n');print(json.dumps({k:v for k,v in e.items()if k!='sourceSha256'}));assert before==after and all(v['returncode']==0 for v in results)
